Code
maxBiomassPerPoint = Math.max(...biomassPoints.map((d) =&gt; d.total_biomass_kg))
biomassRadius = (v) =&gt; 4 + 14 * Math.sqrt(v / maxBiomassPerPoint)


















Code
pointsLayer = {
  const layer = L.layerGroup(
    biomassPoints.map((d) =&gt;
      L.circleMarker([d.lat, d.long], {
        radius: biomassRadius(d.total_biomass_kg),
        color: "#333",
        weight: 1,
        fillColor: sectorColors[d.sector] ?? "#888",
        fillOpacity: 0.7,
      }).bindTooltip(
        `${sectorLabels[d.sector] ?? d.sector} station ${d.station_id}&lt;br&gt;
         ${d.n_trees} trees sampled &middot; ${d.total_biomass_kg.toFixed(1)} kg total biomass`
      )
    )
  );
  layer.addTo(map);
  return layer;
}








